    {
      "name": "add",
      "invoke": "fgos add",
      "description": "Add a work item directly with explicit fields (title/kind/risk/verify/description required). Omit id to auto-generate a collision-free \"tsk-<hash>\" id from title, same generator submit uses.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Optional work item id (positional or --id); omit to auto-generate one from --title."
          },
          "title": {
            "type": "string",
            "description": "Work item title."
          },
          "kind": {
            "type": "string",
            "description": "Work item kind."
          },
          "risk": {
            "type": "string",
            "description": "Work item risk level."
          },
          "verify": {
            "type": "string",
            "description": "Verification command or plan for this item."
          },
          "description": {
            "type": "string",
            "description": "Full-text intake description for this item (required)."
          },
          "deps": {
            "type": "string",
            "description": "Comma-separated list of dependency ids.",
            "multiValueFormat": "csv"
          },
          "refs": {
            "type": "string",
            "description": "Comma-separated list of reference ids/links.",
            "multiValueFormat": "csv"
          },
          "learn": {
            "type": "string",
            "description": "Optional learning note."
          },
          "size": {
            "type": "string",
            "description": "Optional size (light/standard/heavy); omit to use the store default."
          },
          "rigor": {
            "type": "string",
            "description": "Optional rigor (low/standard/high/critical); omit to leave unset."
          },
          "domain": {
            "type": "string",
            "description": "Optional domain; omit to use the store default."
          },
          "footprint": {
            "type": "string",
            "description": "Optional comma-separated list of file paths this item is expected to touch (advisory only).",
            "multiValueFormat": "csv"
          },
          "discovered-from": {
            "type": "string",
            "description": "Optional id of the item this one was discovered from (provenance, not a dependency)."
          },
          "parent": {
            "type": "string",
            "description": "Optional id of the item this one is a decomposed child of (lineage, not a dependency); omit to leave unset."
          },
          "docs-ref": {
            "type": "string",
            "description": "Optional relative path to this item's docs/history/<feature>/ directory (its own CONTEXT.md/plan.md)."
          },
          "acceptance": {
            "type": "string",
            "description": "Optional JSON-encoded array of {text, evidence} Condition-of-Satisfaction clauses (NOT comma-separated — clause text may contain commas).",
            "multiValueFormat": "json-array"
          },
          "goal-tier": {
            "type": "string",
            "description": "Optional goal tier ('mvp' or 'milestone'); omit to leave unset (not a goal)."
          },
          "targets": {
            "type": "string",
            "description": "Optional comma-separated list of ids this goal item considers \"part of\" it (an MVP's targets are milestone ids; a milestone's targets are ordinary work ids).",
            "multiValueFormat": "csv"
          },
          "urgent": {
            "type": "string",
            "description": "Optional urgency level: one of low/medium/high/critical, human-entered. Omit to leave unset — the priority formula reads an absent value as medium, never stored as a default here."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "title",
          "kind",
          "risk",
          "verify",
          "description"
        ]
      },
      "examples": [
        "fgos add build-cli --title \"Build CLI\" --kind feature --risk medium --verify \"npm test\" --description \"Build the CLI entry point per the locked shape\"",
        "fgos add --title \"Build CLI\" --kind feature --risk medium --verify \"npm test\" --description \"Build the CLI entry point per the locked shape\""
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "submit",
      "invoke": "fgos submit",
      "description": "Intake a free-text description: derives the title, classifies tier/kind/risk, auto-generates an id, and adds the item.",
      "parameters": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "Free-text description of the work (positional)."
          },
          "async": {
            "type": "boolean",
            "description": "Mark as async/unattended (submitter does not stay to collaborate). Alias: --unattended."
          },
          "backlog": {
            "type": "boolean",
            "description": "Create the item directly at status \"backlog\" (an idea not yet committed to) instead of the default \"todo\". Promoting it to todo later is a human-only decision."
          },
          "domain": {
            "type": "string",
            "description": "Optional domain; omit to use the store default."
          },
          "discovered-from": {
            "type": "string",
            "description": "Optional id of the item this one was discovered from (provenance, not a dependency)."
          },
          "deps": {
            "type": "string",
            "description": "Comma-separated list of dependency ids.",
            "multiValueFormat": "csv"
          },
          "acceptance": {
            "type": "string",
            "description": "Optional JSON-encoded array of {text, evidence} Condition-of-Satisfaction clauses (NOT comma-separated — clause text may contain commas).",
            "multiValueFormat": "json-array"
          },
          "size": {
            "type": "string",
            "description": "Optional size override (e.g. light/standard/heavy); omit to use classify()'s derived value."
          },
          "rigor": {
            "type": "string",
            "description": "Optional rigor (low/standard/high/critical); omit to leave unset."
          },
          "kind": {
            "type": "string",
            "description": "Optional kind override; omit to use classify()'s derived value."
          },
          "risk": {
            "type": "string",
            "description": "Optional risk override; omit to use classify()'s derived value."
          },
          "verify": {
            "type": "string",
            "description": "Optional verify override: the real, runnable verify command, when the submitter already knows it. Omit to use the placeholder sentinel until context-discovery designs one."
          },
          "docs-ref": {
            "type": "string",
            "description": "Optional relative path to this item's docs/history/<feature>/ directory (its own CONTEXT.md/plan.md); omit to leave unset (can still be added later via edit --docs-ref)."
          }
        },
        "positional": [
          "text"
        ],
        "required": [
          "text"
        ]
      },
      "examples": [
        "fgos submit \"Fix the flaky retry test\" --async",
        "fgos submit \"Fix the flaky retry test\" --verify \"npm test\""
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "discover",
      "invoke": "fgos discover",
      "description": "Run context-discovery for an item at stage discovery or exploring, or query/advance its Workflow run if bound to one. A clear verdict moves the item forward to planning; an unclear verdict at discovery moves it on to exploring and parks it in awaiting-human. When bound to a workflow run, delegates to or reports workflow step status with clear guidance on the unified \"fgos workflow\" door. Errors if the item is at any other stage -- use \"plan\" for a planning-stage item. --verdict lets a caller that already reasoned about clarity supply its own verdict directly.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "config": {
            "type": "string",
            "description": "Path to the runner config (default .fgos/config.json in cwd)."
          },
          "verdict": {
            "type": "string",
            "description": "Optional caller-supplied verdict: \"clear\" or \"unclear\". Omit it only when the item already carries a committed, non-empty CONTEXT.md under its docsRef -- that readLockedContext trust signal advances the item without a verdict. With neither, the call refuses: no subprocess judge stands behind this verb anymore."
          },
          "verify": {
            "type": "string",
            "description": "Required with --verdict clear: the real, runnable verify command for this item."
          },
          "question": {
            "type": "string",
            "description": "Required with --verdict unclear: the question to park the item on in awaiting-human."
          },
          "force": {
            "type": "boolean",
            "description": "Only meaningful with --verdict clear: proceed past a disputed second-pass verify judge instead of parking in awaiting-human. Always logged as a decision naming the disagreement it overrode -- never a silent bypass."
          },
          "size": {
            "type": "string",
            "description": "Only meaningful with --verdict clear: the size this discovery pass judged for the item ('light'/'standard'/'heavy'), applied once the outcome actually resolves clear. Omit to leave the item's size unchanged."
          },
          "rigor": {
            "type": "string",
            "description": "Only meaningful with --verdict clear: the rigor this discovery pass judged for the item ('low'/'standard'/'high'/'critical'), applied once the outcome actually resolves clear. Omit to leave the item's rigor unchanged."
          },
          "kind": {
            "type": "string",
            "description": "Only meaningful with --verdict clear: the kind this discovery pass judged for the item, from the item's own domain vocabulary (coding: bug/chore/design/docs/feature/task). An out-of-vocabulary value is refused as validation before the item moves at all. Omit to leave the item's kind unchanged."
          },
          "risk": {
            "type": "string",
            "description": "Only meaningful with --verdict clear: the risk this discovery pass judged for the item ('light'/'standard'/'heavy'). An out-of-vocabulary value is refused as validation before the item moves at all. Omit to leave the item's risk unchanged."
          },
          "resume": {
            "type": "boolean",
            "description": "When bound to a workflow run, resumes execution of the workflow run."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id"
        ]
      },
      "examples": [
        "fgos discover build-cli",
        "fgos discover build-cli --verdict clear --verify \"npm test\"",
        "fgos discover build-cli --verdict clear --verify \"npm test\" --force"
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "plan",
      "invoke": "fgos plan",
      "description": "Run chia-viec (split-work judgment) for an item at stage planning, or query/advance its Workflow run if bound to one. Moving forward advances to executing (pass-through or split into children) or parks in awaiting-human. When bound to a workflow run, delegates to or reports workflow step status with clear guidance on the unified \"fgos workflow\" door. Errors if the item is not at stage planning -- use \"discover\" for an item still at stage discovery or exploring. --verdict lets a caller supply its own verdict directly.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "config": {
            "type": "string",
            "description": "Path to the runner config (default .fgos/config.json in cwd)."
          },
          "verdict": {
            "type": "string",
            "description": "Optional caller-supplied verdict: \"pass-through\", \"need-human\", or \"decompose\" (this value name is unchanged, tsk-403 D11 -- it names an outcome, not a stage). Omit it only when the item's plan.md declares tiny/small mode -- that skip-and-advance trust signal passes the item through without a verdict. With neither, the call refuses: no subprocess judge stands behind this verb anymore."
          },
          "reason": {
            "type": "string",
            "description": "Required with --verdict need-human or --verdict decompose (optional with pass-through): why this call is verdicting the way it is."
          },
          "children": {
            "type": "string",
            "description": "Required with --verdict decompose: JSON-encoded array of child objects ({title, verify, kind?, risk?, refs?, footprint?, deps?}).",
            "multiValueFormat": "json-array"
          },
          "force": {
            "type": "boolean",
            "description": "Only meaningful with --verdict decompose: proceed past a disputed second-pass verify judge on a child, instead of parking the whole decompose verdict in awaiting-human. Always logged as a decision naming the disagreement it overrode -- never a silent bypass. Mirrors discover --force (tsk-5cf D1b)."
          },
          "validate": {
            "type": "boolean",
            "description": "Explicitly run reviewer validation (planning.validate-plan) before processing the plan verdict."
          },
          "direct": {
            "type": "boolean",
            "description": "Bypass reviewer validation (planning.validate-plan) and proceed directly to resolvePlan."
          },
          "resume": {
            "type": "boolean",
            "description": "When bound to a workflow run, resumes execution of the workflow run."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id"
        ]
      },
      "examples": [
        "fgos plan build-cli",
        "fgos plan build-cli --verdict pass-through --reason \"single-piece, no split needed\""
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "move",
      "invoke": "fgos move",
      "description": "Move a work item to a new status through the FSM, with an optional CAS guard.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "to": {
            "type": "string",
            "description": "Target status to move to."
          },
          "expect": {
            "type": "string",
            "description": "Optional CAS guard: the expected current status."
          },
          "reason": {
            "type": "string",
            "description": "Optional reason; required by the FSM on specific edges (e.g. awaiting-approval -> blocked/todo)."
          },
          "skip-return-guard": {
            "type": "string",
            "description": "Required, non-empty reason to force --to awaiting-approval on a \"doing\" item without going through fgos return's own proof-of-progress checks (branch-advance, clean tree, verify pass). Omit entirely when the item is not \"doing\". Logged to the decision log."
          },
          "answer": {
            "type": "string",
            "description": "Optional answer text when resuming or closing an item out of awaiting-human."
          },
          "approve": {
            "type": "boolean",
            "description": "The owner explicitly approves what the question proposed; only this releases a consent gate. Without it the answer is a clarification and the item is asked again."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id",
          "to"
        ]
      },
      "examples": [
        "fgos move build-cli --to doing",
        "fgos move build-cli --to todo --answer \"Approved\" --approve"
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "retrospective",
      "invoke": "fgos retrospective",
      "description": "Batch sweep, run once per invocation: moves every delivered item to retrospective (the mechanical claim step). Never runs the synthesis itself — that is a session's own separate work while an item sits at retrospective.",
      "parameters": {
        "type": "object",
        "properties": {},
        "positional": [],
        "required": []
      },
      "examples": [
        "fgos retrospective"
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "cleanup",
      "invoke": "fgos cleanup",
      "description": "Finish a cleanup-parked item: verifies the global TTL has elapsed, retrospective produced real content, and (worktree-backed domains only) the merge still resolves on main, then deletes the branch/worktree and closes to done. Any check failing parks cleanup -> blocked with every failing reason.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id"
        ]
      },
      "examples": [
        "fgos cleanup build-cli"
      ],
      "touchesState": true,
      "externalEffect": true,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "compound",
      "invoke": "fgos compound",
      "description": "Tag a retrospective-status work item's outcome with a Diataxis doc-type/doc-path linkage (tutorial | how-to | reference | explanation) -- the producer surface fgos-coding-compounding uses to record its synthesis classification. Requires the item to be at status \"retrospective\"; omitted --doc-type is a no-op.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "doc-type": {
            "type": "string",
            "description": "Optional Diataxis quadrant to tag the capture with: tutorial | how-to | reference | explanation. Omit to leave the item untagged (no-op)."
          },
          "doc-path": {
            "type": "string",
            "description": "Optional end-user doc path this capture links to, alongside --doc-type."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id"
        ]
      },
      "examples": [
        "fgos compound tsk-3o3 --doc-type how-to --doc-path docs/how-to/example.md"
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": "fgos doc reserve/register/promote"
    },
    {
      "name": "edit",
      "invoke": "fgos edit",
      "description": "Patch fields on an existing item (title/description/kind/risk/verify/tier/refs/deps/footprint/action/acceptance/priority/intent/docs-ref/parent/urgent/impact/effort/merge-after). At least one field must be given.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "title": {
            "type": "string",
            "description": "New title."
          },
          "description": {
            "type": "string",
            "description": "New full-text intake description. Must be a non-empty string when present -- unlike refs/deps/footprint, an empty value is rejected as validation rather than clearing the field."
          },
          "kind": {
            "type": "string",
            "description": "New kind."
          },
          "risk": {
            "type": "string",
            "description": "New risk level."
          },
          "verify": {
            "type": "string",
            "description": "New verification command/plan."
          },
          "size": {
            "type": "string",
            "description": "New size (light/standard/heavy)."
          },
          "rigor": {
            "type": "string",
            "description": "New rigor (low/standard/high/critical)."
          },
          "refs": {
            "type": "string",
            "description": "Comma-separated list of reference ids/links (empty string clears the field).",
            "multiValueFormat": "csv"
          },
          "deps": {
            "type": "string",
            "description": "Comma-separated list of dependency ids (empty string clears the field).",
            "multiValueFormat": "csv"
          },
          "footprint": {
            "type": "string",
            "description": "Comma-separated list of file paths this item is expected to touch (advisory only); empty string clears the field.",
            "multiValueFormat": "csv"
          },
          "action": {
            "type": "string",
            "description": "New action directive sentence (e.g. for worker prompt). Must be a non-empty string when present -- unlike refs/deps/footprint, an empty value is rejected as validation rather than clearing the field."
          },
          "parent": {
            "type": "string",
            "description": "New lineage parent id (empty string \"\" clears the field, un-parenting the item)."
          },
          "acceptance": {
            "type": "string",
            "description": "Optional JSON-encoded array of {text, evidence} Condition-of-Satisfaction clauses — replaces the whole array (empty array \"[]\" clears the field). NOT comma-separated — clause text may contain commas.",
            "multiValueFormat": "json-array"
          },
          "priority": {
            "type": "integer",
            "description": "New priority: a non-negative integer, ascending sort (lower = higher priority). Absent stays absent — items without a priority sort after every item that has one."
          },
          "intent": {
            "type": "integer",
            "description": "New intent score: any integer, descending sort (higher = more urgent). Absent stays absent — items without an intent sort after every item that has one."
          },
          "docs-ref": {
            "type": "string",
            "description": "New relative path to this item's docs/history/<feature>/ directory (its own CONTEXT.md/plan.md) — lets an item gain or change this link after creation, e.g. one created via submit (which had no --docs-ref of its own before this field was added here)."
          },
          "urgent": {
            "type": "string",
            "description": "New urgency level: one of low/medium/high/critical, human-entered. Absent reads as medium at the priority formula, never stored as a default here."
          },
          "impact": {
            "type": "number",
            "description": "New impact score: a non-negative number, computed (blocking fan-out + semantic scan + de-risk bonus) — not typically human-entered directly."
          },
          "effort": {
            "type": "number",
            "description": "New effort score: a non-negative number, computed from fgos-coding-planning's mode/flag-count — not typically human-entered directly."
          },
          "merge-after": {
            "type": "string",
            "description": "Comma-separated list of ids this item must merge AFTER (empty string clears the field). A weak, merge-order-only edge — blocks this item's MERGE until every target is resolved, but never blocks its own start/dispatch the way deps does. Validated at set-time: target existence, no self-reference, no cycle (including a cycle mixed with deps/parent).",
            "multiValueFormat": "csv"
          }
        },
        "positional": [
          "id"
        ],
        "required": [
          "id"
        ]
      },
      "examples": [
        "fgos edit build-cli --verify \"npm test -- --grep cli\""
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "resolve-park-reason",
      "invoke": "fgos resolve-park-reason",
      "description": "Clear a stale reason/parkReason left over from a system-error park event on a closed item (status \"done\" or \"wontfix\"), requiring a non-empty --note justifying the resolution for the audit trail.",
