        },
        "positional": [
          "id"
        ],
        "required": [
          "id",
          "note"
        ]
      },
      "examples": [
        "fgos resolve-park-reason tsk-64h --note \"Human confirmed present on main branch\""
      ],
      "touchesState": true,
      "externalEffect": false,
      "paginated": false,
      "deprecated": null
    },
    {
      "name": "ask",
      "invoke": "fgos ask",
      "description": "Park an item in awaiting-human, carrying the question it is waiting on.",
      "parameters": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Work item id (positional or --id)."
          },
          "text": {
            "type": "string",
            "description": "The question text."
          },
          "expect": {
            "type": "string",
            "description": "Optional CAS guard: the expected current status."
          }
        },
        "positional": [
          "id"
        ],
        "required": [
